{
  "candidate": {
    "scope": "orders.upgrade_then_confirm/v1",
    "parent_version": "policy-v0",
    "rules": [
      {
        "hook": "after_upgrade_response",
        "when": "upgrade_outcome_uncertain",
        "steps": [
          { "op": "wait_ticks", "ticks": 1 },
          { "op": "read_current_operation" },
          { "op": "require_receipt", "service": "orders", "status": "SUCCEEDED" }
        ]
      },
      {
        "hook": "after_upgrade_response",
        "when": "upgrade_terminal_failure",
        "steps": [
          { "op": "report_terminal_failure", "service": "orders" }
        ]
      },
      {
        "hook": "before_confirmation",
        "when": "upgrade_receipt_missing",
        "steps": [
          { "op": "read_current_operation" },
          { "op": "require_receipt", "service": "orders", "status": "SUCCEEDED" }
        ]
      },
      {
        "hook": "before_final_report",
        "when": "upgrade_receipt_missing",
        "steps": [
          { "op": "read_current_operation" },
          { "op": "require_receipt", "service": "orders", "status": "SUCCEEDED" }
        ]
      }
    ]
  },
  "explanation": "The verified failures show confirmation and a successful report after an upgrade rejection. This overlay blocks confirmation unless a delivered matching SUCCEEDED orders receipt exists, and blocks any final report claiming upgrade success without that receipt. It preserves original identities and uses only delivered observations."
}

